function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const button=(label,action,ico='',cls='')=>`<button class="button ${cls}" data-action="${action}">${ico?icon(ico):''}<span class="btn-label">${label}</span></button>`;
const ib=(label,action,ico,cls='')=>`<button class="icon-button ${cls}" data-action="${action}" title="${label}" aria-label="${label}">${icon(ico)}</button>`;
const toggle=(label,id,on)=>`<button class="switch" role="switch" aria-label="${label}" aria-checked="${on}" data-toggle="${id}"></button>`;
function sampleImage(variant=0){const accent=variant?'#688366':'#4263eb';return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="960" height="620" viewBox="0 0 960 620"><rect width="960" height="620" fill="#fff"/><rect width="960" height="42" fill="#f2f5fa"/><circle cx="20" cy="21" r="4" fill="#c2ccda"/><circle cx="35" cy="21" r="4" fill="#c2ccda"/><circle cx="50" cy="21" r="4" fill="#c2ccda"/><rect x="295" y="11" width="360" height="20" rx="5" fill="#e6ecf5"/><g font-family="Segoe UI, Microsoft YaHei UI"><text x="475" y="25" font-size="10" text-anchor="middle" fill="#8290a5">panzo / creative-workspace</text><text x="66" y="105" font-size="20" font-weight="600" fill="#25324a">Panzo Studio</text><text x="735" y="105" font-size="12" fill="#8390a2">工作流　　灵感　　关于</text><line x1="66" y1="131" x2="894" y2="131" stroke="#e8edf5"/><rect x="66" y="173" width="113" height="24" rx="12" fill="#eef2ff"/><text x="122" y="189" font-size="11" text-anchor="middle" fill="${accent}">CREATIVE NOTES</text><text x="66" y="256" font-size="39" font-weight="650" fill="#223049">${variant?'把想法，变成作品。':'灵感，捕捉即开始。'}</text><text x="68" y="297" font-size="15" fill="#7b889d">让截图、识别与创作，在同一个工作空间自然衔接。</text><rect x="68" y="331" width="120" height="36" rx="7" fill="${accent}"/><text x="128" y="354" text-anchor="middle" fill="white" font-size="12">探索工作流 →</text><rect x="647" y="170" width="212" height="203" rx="18" fill="#f0f4fb"/><rect x="672" y="191" width="161" height="115" rx="10" fill="white" stroke="#dde5f1"/><rect x="688" y="210" width="52" height="5" rx="2" fill="#8b9ec7"/><rect x="688" y="228" width="126" height="45" rx="4" fill="#e7edfd"/><rect x="688" y="283" width="74" height="4" rx="2" fill="#c9d4e9"/><circle cx="823" cy="340" r="22" fill="${accent}"/><path d="M814 340l6 6 13-14" stroke="white" stroke-width="3" fill="none"/><rect x="66" y="423" width="260" height="136" rx="11" fill="#fafbfe" stroke="#e6ebf4"/><rect x="350" y="423" width="260" height="136" rx="11" fill="#fafbfe" stroke="#e6ebf4"/><rect x="634" y="423" width="260" height="136" rx="11" fill="#fafbfe" stroke="#e6ebf4"/><text x="87" y="454" fill="${accent}" font-size="11">01 / CAPTURE</text><text x="87" y="485" fill="#28364d" font-weight="600" font-size="17">捕捉重要瞬间</text><text x="87" y="518" fill="#8390a2" font-size="12">截图、标注，让重点一目了然。</text><text x="371" y="454" fill="${accent}" font-size="11">02 / UNDERSTAND</text><text x="371" y="485" fill="#28364d" font-weight="600" font-size="17">理解画面内容</text><text x="371" y="518" fill="#8390a2" font-size="12">识别文字，提取内容与灵感。</text><text x="655" y="454" fill="${accent}" font-size="11">03 / CREATE</text><text x="655" y="485" fill="#28364d" font-weight="600" font-size="17">继续自由创作</text><text x="655" y="518" fill="#8390a2" font-size="12">录制、剪辑，再分享你的作品。</text></g></svg>`)}
const S={page:'image',docs:[],active:null,next:1,mode:'ocr',task:'text',tool:'select',zoom:100,theme:'light',jobs:[],plugins:[{id:'ocr',name:'离线文字识别',desc:'在本机提取图片中的文字，支持校对与复制。',icon:'text',version:'内置功能',on:true},{id:'vision',name:'多模态识图',desc:'理解图片、提取表格或自由提问，使用你配置的服务。',icon:'spark',version:'内置功能',on:true},{id:'batch',name:'拼图与批处理',desc:'拼接多张图片，批量转换格式与压缩体积。',icon:'layers',version:'内置功能',on:true},{id:'filter',name:'图片滤镜',desc:'灰度与反色处理，生成新图片并保留原图。',icon:'image',version:'0.1.0 · 独立插件',on:true}],pluginFilter:'all',settingsTab:'appearance',assetsFilter:'all',assetQuery:'',record:{source:'region',audio:true,mic:false,follow:true,recording:false,seconds:0,editing:false,playing:false,tick:0},settings:{endpoint:'https://api.example.com/v1',model:'',key:'',startTray:false,restore:true},modal:null};
try{S.theme=localStorage.getItem('panzo-design-theme')==='dark'?'dark':'light'}catch{}
const pages={image:['image','图片工具','工作空间'],video:['video','录制与视频','工作空间'],library:['folder','素材库','工作空间'],plugins:['grid','插件中心','应用管理'],settings:['settings','设置','应用管理']};
const doc=()=>S.docs.find(d=>d.id===S.active), enabled=id=>S.plugins.find(p=>p.id===id)?.on;
function nav(){for(const [el,keys] of [['#main-nav',['image','video','library']],['#utility-nav',['plugins','settings']]])$(el).innerHTML=keys.map(k=>`<button class="nav-item ${S.page===k?'active':''}" data-page="${k}" title="${pages[k][1]}" aria-current="${S.page===k?'page':'false'}">${icon(pages[k][0])}<span>${pages[k][1]}</span></button>`).join('');$('#session-count').textContent=S.docs.length;$('#session-empty').hidden=!!S.docs.length;$('#session-items').innerHTML=S.docs.slice(-5).map(d=>`<button class="session-item ${d.id===S.active?'selected':''}" data-doc="${d.id}" title="${esc(d.name)}">${icon('image')}<span>${esc(d.name)}</span></button>`).join('');}
function render(){document.documentElement.dataset.theme=S.theme;nav();$('#page-title').textContent=pages[S.page][1];$('#page-eyebrow').textContent=pages[S.page][2];$('#theme-toggle').innerHTML=icon(S.theme==='light'?'moon':'sun');$('#view').innerHTML=({image:imagePage,video:videoPage,library:libraryPage,plugins:pluginsPage,settings:settingsPage}[S.page])();$('#task-count').textContent='后台任务 '+S.jobs.filter(j=>j.status==='running').length;$$('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));if(S.page==='image')requestAnimationFrame(fitDocument)}
function status(t){$('#app-status').textContent=t}let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);status(t)}
function emptyCanvas(){return `<div class="empty-stage"><div class="empty-art"><div class="back-sheet"></div><div class="front-sheet">${icon('image')}</div><span class="plus-badge">${icon('plus')}</span></div><h2>从一张图片开始</h2><p>捕捉屏幕上的灵感，或打开已有图片。<br>标注、识别、编辑，都在这里继续。</p><div class="empty-actions">${button('区域截图','capture','capture','primary large')}${button('打开图片','open-image','folder','large')}</div><div class="drop-hint">也可以拖入图片，或按 <kbd>Ctrl V</kbd> 粘贴</div><div class="empty-features"><span>${icon('pen')} 自由标注</span><span>${icon('text')} 提取文字</span><span>${icon('spark')} 智能识图</span></div></div>`}
function imagePage(){const d=doc();return `<div class="toolbar"><div class="toolbar-group">${button('区域截图','capture','capture','primary')}${button('打开图片','open-image','folder')}${button('长截图','scroll-capture','layers','ghost')}</div><div class="toolbar-group secondary-actions">${button('拼图','collage','grid','ghost')}${button('批处理','batch','layers','ghost')}${ib('图片插件','image-plugins','spark')}${d?ib('关闭当前图片','close-document','close'):''}</div></div><div class="workspace-grid"><section class="canvas-area" aria-label="图片画布">${d?`<div class="image-tabs" role="tablist">${S.docs.map(x=>`<button role="tab" aria-selected="${x.id===S.active}" class="image-tab ${x.id===S.active?'selected':''}" data-doc="${x.id}">${icon('image')}<span>${esc(x.name)}</span>${x.annotations.length?' ·':''}</button>`).join('')}</div><div class="document-tools" aria-label="图片标注工具">${[['select','选择'],['crop','裁剪'],['pen','画笔'],['rect','矩形'],['arrow','箭头'],['text','文字'],['mosaic','马赛克']].map(([k,t])=>ib(t,'tool:'+k,k,S.tool===k?'active':'')).join('')}<i class="separator"></i>${ib('撤销标注','undo','undo')}${ib('贴到桌面','pin','pin')}<i class="separator"></i>${ib('保存图片','save-image','download')}</div>`:''}<div class="canvas" id="canvas">${d?`<div class="document-stage" id="document-stage"><img src="${d.url}" alt="${esc(d.name)}" style="${d.filter?'filter:grayscale(1)':''}"><svg id="annotation-layer" class="annotation-layer" viewBox="0 0 ${d.width} ${d.height}" ${S.tool==='select'?'style="pointer-events:none"':''}>${annotationMarkup(d)}</svg></div>`:emptyCanvas()}</div><div class="canvas-footer"><span>${d?`${d.width} × ${d.height} · PNG${d.annotations.length?' · 有未保存标注':''}`:'支持 PNG、JPG、WebP、GIF 等格式'}</span><div class="zoom-tools">${d?`${ib('缩小','zoom-out','minus')}<span id="zoom-value">${S.zoom}%</span>${ib('放大','zoom-in','plus')}${ib('适应画布','fit','fit')}`:`${icon('shield')} 本地素材`}</div></div></section>${recognitionPanel(d)}</div>`}
function recognitionPanel(d){if(!d)return `<aside class="inspector"><div class="section-title">识别与理解<span class="eyebrow-badge">IMAGE TO IDEAS</span></div><div class="inspector-intro"><div class="large-icon">${icon('spark')}</div><h3>让图片，变成可用的内容</h3><p>打开图片后，在这里选择识别方式，<br>原图与结果始终放在一起。</p></div><div><div class="feature-row">${icon('text')}<div><h4>文字 OCR</h4><p>离线提取图片文字，识别后直接校对、复制。</p></div></div><div class="feature-row">${icon('spark')}<div><h4>多模态识图</h4><p>整理表格、描述画面，也可以针对图片自由提问。</p></div></div></div><p class="privacy-note">${icon('shield')}离线识别在本机完成。使用在线识图时，图片会发送至你配置的服务。</p></aside>`;
const running=S.jobs.find(j=>j.docId===d.id&&j.status==='running');return `<aside class="inspector"><div class="section-title">识别与理解${ib('识图服务设置','service-settings','settings')}</div><div class="segmented" role="tablist" aria-label="识别方式"><button data-mode="ocr" role="tab" aria-selected="${S.mode==='ocr'}" class="${S.mode==='ocr'?'selected':''}">文字 OCR</button><button data-mode="vision" role="tab" aria-selected="${S.mode==='vision'}" class="${S.mode==='vision'?'selected':''}">${icon('spark')} 多模态识图</button></div>${S.mode==='ocr'?`<div class="field"><label for="ocr-language">识别语言</label><select id="ocr-language"><option>自动检测</option><option>简体中文 + English</option><option>English</option></select></div><p class="privacy-note" style="margin:0;padding:0">${icon('shield')}在本机离线处理，无需上传图片</p>`:`<div class="field"><span class="field-label">你想从图片中获得什么？</span><div class="task-chips">${[['text','提取文字'],['table','提取表格'],['describe','描述图片'],['question','自由提问']].map(([k,n])=>`<button class="chip ${S.task===k?'selected':''}" data-task="${k}">${n}</button>`).join('')}</div></div><details ${S.task==='question'?'open':''}><summary>补充要求${S.task==='question'?'':'（可选）'}</summary><div class="field"><textarea id="recognition-prompt" placeholder="例如：保留表格结构，用中文回答">${esc(d.prompt||'')}</textarea></div></details>`}${running?`<div class="job-inline"><span class="spinner"></span>正在处理 ${esc(d.name)}</div>${button('取消识别','cancel-ocr','','full')}`:`<button class="button primary full" data-action="recognize" ${enabled(S.mode)?'':'disabled'}>${icon(S.mode==='ocr'?'text':'spark')}开始识别</button>${enabled(S.mode)?'':'<p class="privacy-note">此功能已停用，可到插件中心重新启用。</p>'}`}<section class="result-block"><div class="section-title">识别结果<span class="subtle">${d.result?'可编辑':'等待识别'}</span></div><textarea id="ocr-result" class="result-editor" aria-label="识别结果，可直接校对" placeholder="识别完成后，结果会显示在这里。&#10;可以直接校对文字。">${esc(d.result||'')}</textarea><div class="result-actions"><span>${d.result?d.result.length+' 字 · 演示结果':'结果跟随当前图片保存'}</span>${button('复制','copy-result','copy','small')}</div></section></aside>`}
function annotationMarkup(d){return d.annotations.map(a=>a.kind==='rect'?`<rect x="${a.x}" y="${a.y}" width="${a.w}" height="${a.h}" fill="none" stroke="#4263eb" stroke-width="4" rx="2"/>`:`<path d="${a.path}" fill="none" stroke="#4263eb" stroke-width="4" stroke-linecap="round"/>`).join('')}
function fitDocument(){const d=doc(),s=$('#document-stage'),c=$('#canvas');if(!d||!s||!c)return;const r=c.getBoundingClientRect(),scale=Math.max(.05,Math.min((r.width-80)/d.width,(r.height-80)/d.height,1));s.style.width=d.width*scale*S.zoom/100+'px';s.style.height=d.height*scale*S.zoom/100+'px';if($('#zoom-value'))$('#zoom-value').textContent=Math.round(scale*S.zoom)+'%'}
function videoPage(){return S.record.editing?videoEditor():`<div class="scroll-page"><div class="content-heading"><div><h2>录下你的下一次精彩</h2><p>选择录制区域，调整声音和镜头，然后开始。</p></div><span class="tag blue">${S.record.recording?'录制演示中':'准备录制'}</span></div><div class="record-grid"><section class="record-preview card"><div class="segmented" aria-label="录制来源">${[['monitor','全屏','screen'],['window','窗口','window'],['capture','区域','region']].map(([i,n,k])=>`<button data-source="${k}" class="${S.record.source===k?'selected':''}">${icon(i)} ${n}</button>`).join('')}</div><div class="monitor"><img src="${sampleImage()}" alt="录制区域示意图"><span class="monitor-label">${{region:'已选择区域 · 1280 × 720',screen:'显示器 1 · 1920 × 1080',window:'Panzo Studio · 应用窗口'}[S.record.source]}</span></div><div class="record-bottom">${S.record.recording?`<div class="record-timer"><i class="red-dot"></i><span id="record-time">${time(S.record.seconds)}</span></div>${button('停止录制','stop-record','stop','danger large')}`:`<div><p>${icon('folder')} 视频 / Panzo</p>${button('重新选择区域','choose-region','','ghost small')}</div>${button('开始录制','start-record','video','primary large')}`}</div></section><aside class="record-settings card"><div class="section-title">录制设置<span class="subtle">自动保存</span></div><div class="two-fields"><div class="field"><label for="record-fps">帧率</label><select id="record-fps"><option>30 fps</option><option>60 fps</option><option>24 fps</option></select></div><div class="field"><label for="countdown">倒计时</label><select id="countdown"><option>3 秒</option><option>无</option><option>5 秒</option></select></div></div><div class="setting-row"><div><h3>${icon('volume')} 系统声音</h3><p>录制电脑播放的声音</p></div>${toggle('系统声音','audio',S.record.audio)}</div><div class="setting-row"><div><h3>${icon('mic')} 麦克风</h3><p>默认输入设备</p></div>${toggle('麦克风','mic',S.record.mic)}</div><div class="setting-row"><div><h3>${icon('select')} 鼠标跟随缩放</h3><p>开启后自动突出光标区域</p></div>${toggle('鼠标跟随缩放','follow',S.record.follow)}</div><p class="privacy-note">${icon('help')}录制完成后直接进入编辑，可以继续调整鼠标跟随效果。</p></aside></div><div class="recent-project card"><div class="project-info"><span class="plugin-icon">${icon('video')}</span><div><h3>产品操作演示.panzo</h3><p>示例工程 · 12 秒 · 1920 × 1080</p></div></div>${button('打开示例工程','open-video','arrow','ghost')}</div></div>`}
function videoEditor(){return `<div class="toolbar"><div class="toolbar-group">${button('新录制','new-record','video')}${ib('撤销','video-undo','undo')}<span class="tag">产品操作演示.panzo</span></div><div class="toolbar-group"><span class="tag green">演示工程</span>${button('导出','export','download','primary')}</div></div><div class="editor-layout"><section class="video-editor"><div class="video-screen"><div class="composition"><img src="${sampleImage()}" alt="视频画面示例"></div></div><div class="playback"><div>${ib(S.record.playing?'暂停':'播放','play',S.record.playing?'pause':'play')}<span class="timecode" id="video-time">${time(S.record.tick)} / 00:12</span></div><div>${button('当前帧截图','frame-capture','capture','small ghost')}${ib('适应画布','video-fit','fit')}</div></div><div class="timeline"><div class="timeline-header"><span>时间线</span><div>${ib('分割视频','split-video','crop')}${ib('删除片段','delete-video','trash')}</div></div><input type="range" min="0" max="12" step="0.1" value="${S.record.tick}" id="video-scrub" aria-label="播放位置"><div class="timeline-track"><span class="track-name">视频</span><div class="track">${icon('video')}　产品操作演示　12 秒</div></div><div class="timeline-track"><span class="track-name">镜头</span><div class="track camera ${S.record.follow?'':'off'}">${icon('select')}　鼠标跟随缩放</div></div></div></section><aside class="inspector"><div class="section-title">画面与镜头</div><div class="field"><label for="aspect">画布比例</label><select id="aspect"><option>16:9 · 宽屏</option><option>9:16 · 竖屏</option><option>1:1 · 方形</option></select></div><div class="field"><label>背景</label><div class="task-chips"><button class="chip selected" data-action="background:blue">雾蓝</button><button class="chip" data-action="background:warm">暖白</button><button class="chip" data-action="background:dark">深灰</button></div></div><div class="setting-row"><div><h3>鼠标跟随缩放</h3><p>随时开启或关闭</p></div>${toggle('鼠标跟随缩放','follow',S.record.follow)}</div><div class="field"><label for="camera-scale">缩放倍率</label><input id="camera-scale" type="range" min="1" max="3" step="0.1" value="1.6"><small>1.6× · 平滑跟随</small></div><div class="setting-row"><div><h3>系统声音</h3><p>保留录制时的声音</p></div>${toggle('系统声音','audio',S.record.audio)}</div><p class="privacy-note">${icon('shield')}切换工作空间会保留播放位置和编辑内容。</p></aside></div>`}
const baseAssets=[{id:'a1',name:'灵感工作流.png',type:'image',tag:'PNG',meta:'960 × 620',when:'今天 14:32',url:sampleImage()},{id:'a2',name:'产品操作演示.panzo',type:'video',tag:'00:12',meta:'1920 × 1080',when:'今天 13:48',url:sampleImage(1)},{id:'a3',name:'工作台布局参考.png',type:'image',tag:'PNG',meta:'960 × 620',when:'昨天 18:20',url:sampleImage(1)},{id:'a4',name:'交互演示.gif',type:'gif',tag:'GIF',meta:'960 × 620',when:'昨天 16:05',url:sampleImage()}];
function allAssets(){return [...S.docs.map(d=>({id:'doc'+d.id,name:d.name,type:'image',tag:'PNG',meta:d.width+' × '+d.height,when:'当前会话',url:d.url})),...baseAssets]}
function libraryPage(){const assets=allAssets().filter(a=>(S.assetsFilter==='all'||a.type===S.assetsFilter)&&a.name.toLowerCase().includes(S.assetQuery.toLowerCase()));return `<div class="scroll-page"><div class="content-heading"><div><h2>每一份素材，都有归处</h2><p>继续最近的创作，或将已有素材带回工作空间。</p></div>${button('导入素材','open-image','plus')}</div><div class="subnav-row"><div class="plain-tabs" role="tablist">${[['all','全部'],['image','图片'],['video','视频工程'],['gif','GIF']].map(([k,n])=>`<button class="${k===S.assetsFilter?'selected':''}" data-filter="${k}">${n}</button>`).join('')}</div><div class="search-field">${icon('search')}<input id="asset-search" class="input" placeholder="搜索素材名称" aria-label="搜索素材" value="${esc(S.assetQuery)}"></div></div><div class="assets-grid" id="assets-grid">${assetCards(assets)}</div></div>`}
function assetCards(assets){return assets.map(a=>`<button class="asset-card card" data-asset="${a.id}"><div class="asset-image"><img src="${a.url}" alt="${esc(a.name)}的预览"><span class="tag">${a.tag}</span></div><div class="asset-meta"><h3>${esc(a.name)}</h3><p><span>${a.meta}</span><span>${a.when}</span></p></div></button>`).join('')||'<div class="empty-search">没有匹配的素材，试试其他关键词。</div>'}
function pluginsPage(){const list=S.plugins.filter(p=>S.pluginFilter==='all'||p.on);return `<div class="scroll-page"><div class="content-heading"><div><h2>让 Panzo，适合你的工作方式</h2><p>按需添加功能，统一在工作空间中使用。</p></div>${button('安装本地插件','install-plugin','plus','primary')}</div><div class="subnav-row"><div class="plain-tabs"><button data-plugin-filter="all" class="${S.pluginFilter==='all'?'selected':''}">已安装 <span class="badge-counter">${S.plugins.length}</span></button><button data-plugin-filter="on" class="${S.pluginFilter==='on'?'selected':''}">已启用</button></div><span class="tag">本地功能管理</span></div><div class="plugin-list">${list.map(p=>`<article class="plugin-card card"><div class="plugin-top"><span class="plugin-icon ${p.id==='ocr'?'green':''}">${icon(p.icon)}</span><div><h3>${esc(p.name)}</h3><p>${esc(p.version)}</p></div>${toggle(p.name,'plugin:'+p.id,p.on)}</div><p class="plugin-description">${esc(p.desc)}</p><div class="plugin-bottom"><span class="tag ${p.on?'green':''}">${p.on?'● 已启用':'已停用'}</span>${button('管理','plugin:'+p.id,'chevron','ghost small')}</div></article>`).join('')}</div><div class="info-banner">${icon('shield')}<div><strong>功能可以卸载，作品始终保留。</strong><br>停用会阻止新任务，已开始的任务继续完成。原生插件以当前用户权限运行，请从信任的来源安装。</div></div></div>`}
function settingsPage(){return `<div class="scroll-page"><div class="settings-layout"><nav class="settings-nav" aria-label="设置分类">${[['appearance','外观与行为','sun'],['service','识图服务','spark'],['shortcuts','快捷键','keyboard'],['storage','存储与隐私','shield']].map(([k,n,i])=>`<button class="${S.settingsTab===k?'selected':''}" data-settings="${k}">${icon(i)}${n}</button>`).join('')}</nav><div class="settings-content">${settingsContent()}</div></div></div>`}
function settingsContent(){if(S.settingsTab==='service')return `<h2>识图服务</h2><p class="subtitle">连接你自己的多模态服务，在图片区直接使用。</p><div class="settings-card card"><div class="section-title">服务连接<span class="tag blue">自定义 API</span></div><div class="service-form"><div class="field"><label for="api-endpoint">服务地址</label><input id="api-endpoint" data-setting="endpoint" value="${esc(S.settings.endpoint)}" spellcheck="false"><small>支持兼容的 Chat Completions 接口</small></div><div class="field"><label for="api-model">模型名称</label><input id="api-model" data-setting="model" value="${esc(S.settings.model)}" placeholder="填写服务支持的视觉模型" spellcheck="false"></div><div class="field"><label for="api-key">API Key</label><input id="api-key" data-setting="key" type="password" autocomplete="off" value="${esc(S.settings.key)}" placeholder="设计预览，请勿输入真实密钥"><small>正式应用由本机加密保存；原型不会保存密钥或连接外部服务。</small></div><div class="button-row">${button('保存配置','save-service','','primary')}${button('测试连接','test-service','link')}</div></div></div><div class="info-banner">${icon('shield')}<div>只有你主动使用在线识图时，图片才会发送到配置的服务。离线 OCR 始终可单独使用。</div></div>`;
if(S.settingsTab==='shortcuts')return `<h2>快捷键</h2><p class="subtitle">常用操作触手可及，编辑时保持专注。</p><div class="settings-card card">${[['搜索功能','Ctrl K'],['打开图片','Ctrl O'],['粘贴图片','Ctrl V'],['撤销标注','Ctrl Z'],['关闭面板 / 取消当前操作','Esc']].map(([n,k])=>`<div class="setting-row"><h3>${n}</h3><kbd>${k}</kbd></div>`).join('')}</div>`;
if(S.settingsTab==='storage')return `<h2>存储与隐私</h2><p class="subtitle">掌控素材、识图服务和插件的使用范围。</p><div class="settings-card card"><div class="section-title">本地工作空间</div><div class="setting-row"><div><h3>素材存储</h3><p>视频 / Panzo · 原图与处理结果独立保存</p></div>${button('查看说明','storage-info','','small')}</div><div class="setting-row"><div><h3>在线识图</h3><p>主动开始后，将当前图片发送到配置的服务</p></div><span class="tag">按需使用</span></div><div class="setting-row"><div><h3>原生插件</h3><p>独立后台进程，拥有当前用户权限</p></div>${button('管理','go-plugins','','small')}</div></div>`;
return `<h2>外观与行为</h2><p class="subtitle">熟悉的工作空间，用你喜欢的方式呈现。</p><section class="settings-card card"><div class="section-title">界面主题<span class="subtle">即时生效</span></div><div class="theme-cards">${['light','dark'].map(t=>`<button data-theme-choice="${t}" class="theme-card ${S.theme===t?'selected':''}"><div class="theme-mini ${t}"><aside><i></i><i></i><i></i></aside><div><header></header><main></main></div></div>${t==='light'?'浅色 · 清晰明快':'深色 · 专注画面'}</button>`).join('')}</div></section><section class="settings-card card"><div class="section-title">工作习惯</div><div class="setting-row"><div><h3>恢复上次工作空间</h3><p>打开应用后继续之前的标签与素材</p></div>${toggle('恢复上次工作空间','restore',S.settings.restore)}</div><div class="setting-row"><div><h3>关闭窗口后最小化到托盘</h3><p>保留快捷截图和后台任务</p></div>${toggle('关闭后进入托盘','startTray',S.settings.startTray)}</div></section><p class="privacy-note">${icon('help')}设计预览仅保存主题偏好。工作空间恢复选项属于后续实现目标。</p>`}
function addDoc(url=sampleImage(S.docs.length%2),name='',width=960,height=620){const d={id:S.next++,name:name||`示例截图 ${S.next-1}.png`,width,height,url,result:'',prompt:'',annotations:[]};S.docs.push(d);S.active=d.id;S.page='image';S.zoom=100;S.tool='select';render();return d}
function time(n){return Math.floor(n/60).toString().padStart(2,'0')+':'+Math.floor(n%60).toString().padStart(2,'0')}
function theme(t){S.theme=t;try{localStorage.setItem('panzo-design-theme',t)}catch{}render()}
let restoreFocus=null;function modal(title,body,actions=''){restoreFocus=document.activeElement;S.modal=title;$('#dialog').innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${title}</h2>${ib('关闭','close-modal','close')}</div>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}`;$('#overlay').hidden=false;requestAnimationFrame(()=>$('#dialog input, #dialog button')?.focus())}
function closeModal(){S.modal=null;$('#overlay').hidden=true;restoreFocus?.isConnected&&restoreFocus.focus()}
function recognize(){const d=doc();if(!d||!enabled(S.mode)||S.jobs.some(j=>j.docId===d.id&&j.status==='running'))return;const job={id:Date.now(),docId:d.id,name:'识别 '+d.name,status:'running',mode:S.mode,task:S.task};S.jobs.push(job);render();status('正在识别 '+d.name+'，可以继续切换页面');job.timer=setTimeout(()=>{if(job.status!=='running')return;job.status='done';d.result=job.mode==='vision'&&job.task==='table'?'【演示识别结果】\n项目\t功能\t状态\n捕捉\t截图与标注\t可使用\n理解\tOCR 与多模态\t可使用\n创作\t录制与剪辑\t可使用':job.mode==='vision'&&job.task!=='text'?'【演示识别结果】\n这是一张介绍创作工作流的页面截图。\n\n页面按“捕捉 → 理解 → 创作”组织信息，主要内容包括截图标注、文字提取和视频录制。':'【演示识别结果】\n灵感，捕捉即开始。\n\n让截图、识别与创作，在同一个工作空间自然衔接。\n\n01 捕捉重要瞬间\n截图、标注，让重点一目了然。\n\n02 理解画面内容\n识别文字，提取内容与灵感。\n\n03 继续自由创作\n录制、剪辑，再分享你的作品。';render();toast(d.name+' 的演示识别已完成，结果保留在原图旁');},1800)}
function showHelp(){modal('Panzo · 新工作区设计',`<p>这是交互设计原型，用来评审布局、视觉和操作流程。当前运行的原生应用尚未替换界面。</p><ul><li>点击“区域截图”进入示例素材，也支持导入本地图片。</li><li>开始识别后可切换图片或页面，演示结果会回到原图。</li><li>支持矩形 / 画笔标注与撤销，其他工具展示操作位置。</li><li>录制、导出和插件安装为流程演示，不执行实际系统操作。</li><li>浅色与深色共用同一布局；主题偏好保存在浏览器。</li></ul>`,button('开始体验','close-modal','','primary'))}
function showCommands(){modal('搜索功能','<div class="field"><input id="command-query" placeholder="输入功能名称…" aria-label="搜索功能名称"></div><div id="command-results" class="command-list"></div>');commandResults('');setTimeout(()=>$('#command-query')?.focus(),0)}
function commandResults(q){const commands=[['区域截图','capture','capture',''],['打开图片','open-image','folder','Ctrl O'],['文字识别','go-image','text',''],['录制与视频','go-video','video',''],['素材库','go-library','folder',''],['插件中心','go-plugins','grid',''],['识图服务设置','service-settings','settings','']];$('#command-results').innerHTML=commands.filter(c=>c[0].includes(q)).map(([n,a,i,k])=>`<button class="command-item" data-command="${a}">${icon(i)}${n}${k?`<kbd>${k}</kbd>`:''}</button>`).join('')||'<p>没有匹配的功能</p>'}
S.panels={};S.drafts={};
function sidePanel(title,body,actions=''){S.panels[S.page]={title,body,actions};paintPanel()}
function paintPanel(){const p=S.panels[S.page],el=$('.inspector');if(p&&el)el.innerHTML=`<div class="section-title">${p.title}${ib('收起面板','close-panel','close')}</div>${p.body}<div class="button-row">${p.actions}</div>`}
const baseRender=render;render=function(){baseRender();paintPanel();for(const [id,value] of Object.entries(S.drafts)){const el=document.getElementById(id);if(el)el.value=value}};
function action(a){
if(a.startsWith('go-')){S.page=a.slice(3);render();return}
if(a.startsWith('tool:')){S.tool=a.slice(5);render();if(!['select','rect','pen'].includes(S.tool))toast('当前展示工具的交互位置，原型支持矩形与画笔试画');return}
if(a.startsWith('plugin:')){const p=S.plugins.find(x=>x.id===a.slice(7));modal(p.name,`<p>${esc(p.desc)}</p><div class="setting-row"><h3>版本</h3><span class="tag">${esc(p.version)}</span></div><div class="setting-row"><h3>当前状态</h3><span class="tag ${p.on?'green':''}">${p.on?'已启用':'已停用'}</span></div><p>停用将阻止新任务，已开始的任务继续完成。卸载不会删除你的图片和识别结果。</p>`,button(p.on?'停用':'启用','toggle-plugin:'+p.id)+(p.id==='filter'?button('回退上一版本','rollback-plugin')+button('卸载插件','uninstall-filter'):'')+button('完成','close-modal','','primary'));return}
if(a.startsWith('toggle-plugin:')){const p=S.plugins.find(x=>x.id===a.slice(14));p.on=!p.on;closeModal();render();toast(p.name+(p.on?'已启用':'已停用'));return}
if(a.startsWith('background:')){$('.composition').style.background=({blue:'linear-gradient(130deg,#d8e5fd,#eadcfe)',warm:'#eee8e1',dark:'#30394b'})[a.slice(11)];return}
switch(a){
case 'capture':addDoc();toast('已加入示例截图，可试画标注或开始演示识别');break;
case 'scroll-capture':addDoc(sampleImage(),'长截图流程示例.png');toast('设计预览：实际选区与滚动采集使用现有原生能力');break;
case 'open-image':$('#file-input').click();break;
case 'recognize':recognize();break;
case 'cancel-ocr':{const j=S.jobs.find(j=>j.docId===S.active&&j.status==='running');if(j){clearTimeout(j.timer);j.status='cancelled'}render();toast('已取消识别，原图保留');break}
case 'copy-result':if(!doc()?.result){toast('识别后可复制结果');break}if(navigator.clipboard)navigator.clipboard.writeText(doc().result).then(()=>toast('结果已复制')).catch(()=>toast('浏览器未允许复制，可选中文字后按 Ctrl C'));else toast('请选中文字后按 Ctrl C 复制');break;
case 'service-settings':S.page='settings';S.settingsTab='service';render();break;
case 'undo':if(doc()?.annotations.length){doc().annotations.pop();render();toast('已撤销上一处标注')}break;
case 'zoom-in':S.zoom=Math.min(200,S.zoom+25);render();break;
case 'zoom-out':S.zoom=Math.max(25,S.zoom-25);render();break;
case 'fit':S.zoom=100;render();break;
case 'close-document':if(doc()?.annotations.length)modal('关闭这张图片？','<p>这张图片还有原型中的未保存标注，关闭后会丢弃这些标注。其他图片保持不变。</p>',button('继续编辑','close-modal')+button('丢弃并关闭','discard-document','','primary'));else action('discard-document');break;
case 'discard-document':{const old=S.active;S.docs=S.docs.filter(d=>d.id!==old);S.jobs.filter(j=>j.docId===old&&j.status==='running').forEach(j=>{clearTimeout(j.timer);j.status='cancelled'});S.active=S.docs.at(-1)?.id??null;closeModal();render();break}
case 'image-plugins':sidePanel('图片插件',`<p class="privacy-note">处理当前图片，结果作为新图片加入工作空间，原图保留。</p><div class="field"><label for="image-filter">插件操作</label><select id="image-filter"><option>图片滤镜 · 灰度</option></select></div>`,button('运行演示','run-filter','','primary')+button('管理插件','go-plugins'));break;
case 'run-filter':if(!doc()){toast('请先打开图片');break}if(!enabled('filter')){toast('请先在插件中心启用图片滤镜');break}{const d=doc(),out=addDoc(d.url,'灰度 · '+d.name,d.width,d.height);out.filter=true;render();toast('已生成灰度预览，原图保持不变');break}
case 'close-panel':delete S.panels[S.page];render();break;
case 'install-plugin':modal('安装本地插件',`<div class="empty-stage" style="padding:25px;box-shadow:none">${icon('grid')}<h3 style="margin-top:10px">添加你需要的功能</h3><p>选择下载好的 .panzoplugin 文件，<br>安装前查看来源、版本和访问范围。</p>${button('选择插件文件','choose-plugin','folder','primary')}</div><p class="privacy-note">此设计原型只展示包信息，不安装或执行插件。</p>`);break;
case 'choose-plugin':$('#plugin-input').click();break;
case 'trust-plugin':closeModal();toast('安装确认流程演示完成；未写入应用插件目录');break;
case 'rollback-plugin':toast('当前示例没有可回退版本，保留现有插件');break;
case 'uninstall-filter':S.plugins=S.plugins.filter(p=>p.id!=='filter');closeModal();render();toast('示例插件已从原型移除，素材保留');break;
case 'start-record':S.record.recording=true;S.record.seconds=0;render();toast('开始录制流程演示 · 未采集屏幕或声音');break;
case 'stop-record':S.record.recording=false;S.record.editing=true;render();toast('录制流程演示完成，已进入示例工程');break;
case 'choose-region':toast('正式应用将在此进入桌面区域选择，完成后返回当前页面');break;
case 'open-video':S.record.editing=true;render();break;
case 'new-record':S.record.editing=false;S.record.playing=false;delete S.panels.video;render();break;
case 'play':S.record.playing=!S.record.playing;render();break;
case 'frame-capture':addDoc(sampleImage(),'视频帧示例.png');toast('视频工程和播放位置保留，可从导航返回');break;
case 'export':sidePanel('导出视频',`<p class="privacy-note">输出一份适合分享的视频或 GIF。</p><div class="two-fields"><div class="field"><label for="export-format">格式</label><select id="export-format"><option>MP4</option><option>GIF</option></select></div><div class="field"><label for="export-fps">帧率</label><select id="export-fps"><option>30 fps</option><option>24 fps</option><option>15 fps</option><option>10 fps</option></select></div></div><div class="field"><label for="export-size">分辨率</label><select id="export-size"><option>1920 × 1080</option><option>1280 × 720</option><option>原始尺寸</option></select></div><div class="export-summary"><span>时长 12 秒</span><span>包含鼠标跟随：${S.record.follow?'是':'否'}</span></div>`,button('预览导出流程','export-demo','download','primary'));break;
case 'export-demo':sidePanel('导出流程演示','<p>正式应用会在后台导出，你可以切换到其他工作空间。</p><div class="progress-track"><i style="width:100%"></i></div><p class="privacy-note">原型不生成 MP4 / GIF 文件。</p>',button('完成','close-panel','','primary'));break;
case 'close-modal':closeModal();break;
case 'save-service':toast('仅更新本次预览状态；未保存密钥、未修改应用配置');break;
case 'test-service':toast('连接检查界面演示；原型不会请求外部服务');break;
case 'storage-info':modal('本地素材存储','<p>正式应用在素材库保存截图和处理结果。插件卸载不删除素材；在线识图仅在主动调用时发送当前图片。</p>',button('知道了','close-modal','','primary'));break;
case 'collage':case 'batch':sidePanel(a==='collage'?'拼图':'批量处理',`<p class="privacy-note">选择素材后，继续设置布局或输出参数。</p><div class="field"><label for="image-operation">${a==='collage'?'布局':'输出格式'}</label><select id="image-operation">${a==='collage'?'<option>纵向拼接</option><option>横向拼接</option><option>网格</option>':'<option>PNG</option><option>JPG</option><option>WebP</option>'}</select></div><p class="privacy-note">本原型展示参数组织；实际处理沿用现有功能。</p>`,button('选择图片','open-image','folder','primary'));break;
case 'pin':toast('正式应用会将当前图片贴到桌面；原型不创建置顶窗口');break;
case 'save-image':toast('设计预览：保存操作将调用宿主的图片导出，当前原型未导出标注');break;
case 'video-fit':case 'video-undo':case 'split-video':case 'delete-video':toast('此处为视频编辑操作位置，实际剪辑由现有引擎完成');break;
}}
function selectPage(k){S.page=k;render()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.page)selectPage(b.dataset.page);else if(b.dataset.doc){S.active=+b.dataset.doc;S.page='image';S.zoom=100;render()}else if(b.dataset.mode){S.mode=b.dataset.mode;render()}else if(b.dataset.task){S.task=b.dataset.task;render()}else if(b.dataset.toggle){const id=b.dataset.toggle;if(id.startsWith('plugin:')){const p=S.plugins.find(p=>p.id===id.slice(7));p.on=!p.on;toast(p.name+(p.on?'已启用':'已停用，已有任务继续完成'))}else if(id in S.record)S.record[id]=!S.record[id];else S.settings[id]=!S.settings[id];render()}else if(b.dataset.source){S.record.source=b.dataset.source;render()}else if(b.dataset.filter){S.assetsFilter=b.dataset.filter;render()}else if(b.dataset.pluginFilter){S.pluginFilter=b.dataset.pluginFilter;render()}else if(b.dataset.settings){S.settingsTab=b.dataset.settings;render()}else if(b.dataset.themeChoice)theme(b.dataset.themeChoice);else if(b.dataset.asset){const a=allAssets().find(a=>a.id===b.dataset.asset);if(a.type==='video'){S.page='video';S.record.editing=true;render()}else if(a.id.startsWith('doc')){S.active=+a.id.slice(3);S.page='image';render()}else addDoc(a.url,a.name)}else if(b.dataset.command){closeModal();action(b.dataset.command)}else if(b.dataset.action)action(b.dataset.action)});
document.addEventListener('change',e=>{if(['ocr-language','record-fps','countdown','camera-scale','aspect','export-format','export-fps','export-size','image-operation'].includes(e.target.id))S.drafts[e.target.id]=e.target.value});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='ocr-result'&&doc())doc().result=t.value;else if(t.id==='recognition-prompt'&&doc())doc().prompt=t.value;else if(t.dataset.setting)S.settings[t.dataset.setting]=t.value;else if(t.id==='asset-search'){S.assetQuery=t.value;$('#assets-grid').innerHTML=assetCards(allAssets().filter(a=>(S.assetsFilter==='all'||a.type===S.assetsFilter)&&a.name.toLowerCase().includes(S.assetQuery.toLowerCase())))}else if(t.id==='command-query')commandResults(t.value);else if(t.id==='video-scrub'){S.record.tick=+t.value;$('#video-time').textContent=time(S.record.tick)+' / 00:12'}});
async function importFiles(files){let count=0;for(const f of [...files]){if(!f.type.startsWith('image/'))continue;if(f.size>20*1024*1024){toast('原型仅预览 20 MB 以内的图片');continue}const url=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)});const im=new Image();await new Promise((res,rej)=>{im.onload=res;im.onerror=rej;im.src=url}).catch(()=>null);if(!im.naturalWidth)continue;addDoc(url,f.name,im.naturalWidth,im.naturalHeight);count++}if(count)toast('已在本地预览 '+count+' 张图片；文件未上传')}
$('#file-input').addEventListener('change',e=>{importFiles(e.target.files).catch(()=>toast('图片无法读取'));e.target.value=''});
$('#plugin-input').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>48*1024*1024){toast('文件过大，无法预览');return}try{const p=JSON.parse(await f.text()),m=p.manifest;if(p.format!==1||!m?.id||!m?.name)throw Error();modal('确认插件来源',`<div class="plugin-top"><span class="plugin-icon">${icon('grid')}</span><div><h3>${esc(m.name)}</h3><p>${esc(m.version)} · ${esc(m.publisher)}（作者声明）</p></div></div><p>${esc(m.description)}</p><div class="info-banner">${icon('shield')}<div>原生插件拥有当前用户权限。校验值不能证明发布者身份，请只安装信任的来源。</div></div><p>原型只读取清单预览，不验证 EXE 或执行安装。</p>`,button('取消','close-modal')+button('信任并安装（演示）','trust-plugin','','primary'))}catch{toast('不是可预览的 Panzo 插件包')}});
document.addEventListener('dragover',e=>{if(!$('#canvas'))return;e.preventDefault();$('#canvas').classList.add('dragging')});document.addEventListener('dragleave',e=>{if(!e.relatedTarget)$('#canvas')?.classList.remove('dragging')});document.addEventListener('drop',e=>{if(!$('#canvas'))return;e.preventDefault();$('#canvas').classList.remove('dragging');importFiles(e.dataTransfer.files).catch(()=>toast('图片无法读取'))});document.addEventListener('paste',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName))return;const files=[...(e.clipboardData?.items||[])].filter(i=>i.type.startsWith('image/')).map(i=>i.getAsFile()).filter(Boolean);if(files.length){e.preventDefault();importFiles(files).catch(()=>toast('剪贴板图片无法读取'))}});
let drawing=null;document.addEventListener('pointerdown',e=>{if(e.target.id!=='annotation-layer'||!['rect','pen'].includes(S.tool))return;const r=e.target.getBoundingClientRect(),d=doc(),x=(e.clientX-r.x)/r.width*d.width,y=(e.clientY-r.y)/r.height*d.height;drawing={id:d.id,x,y,points:[[x,y]],rect:r,tool:S.tool};e.target.setPointerCapture(e.pointerId)});document.addEventListener('pointermove',e=>{if(!drawing)return;const d=S.docs.find(d=>d.id===drawing.id);if(!d)return;const x=(e.clientX-drawing.rect.x)/drawing.rect.width*d.width,y=(e.clientY-drawing.rect.y)/drawing.rect.height*d.height;drawing.points.push([x,y]);drawing.current=drawing.tool==='rect'?{kind:'rect',x:Math.min(x,drawing.x),y:Math.min(y,drawing.y),w:Math.abs(x-drawing.x),h:Math.abs(y-drawing.y)}:{kind:'path',path:drawing.points.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' ')};$('#annotation-layer').innerHTML=annotationMarkup({...d,annotations:[...d.annotations,drawing.current]})});document.addEventListener('pointerup',()=>{if(!drawing)return;const d=S.docs.find(d=>d.id===drawing.id);if(d&&drawing.current)d.annotations.push(drawing.current);drawing=null;render()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(S.modal)closeModal();else if(drawing){drawing=null;render()}else if(S.panels[S.page])action('close-panel');return}if(S.modal&&e.key==='Tab'){const focus=[...$('#dialog').querySelectorAll('button,input,textarea,select')].filter(e=>!e.disabled);const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showCommands();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='o'){e.preventDefault();action('open-image');return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(e.target.tagName)&&S.page==='image'){e.preventDefault();action('undo')}});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeModal()});$('#command-search').onclick=showCommands;$('#theme-toggle').onclick=()=>theme(S.theme==='light'?'dark':'light');$('#help').onclick=showHelp;$('#tour').onclick=showHelp;$('#privacy').onclick=()=>{S.page='settings';S.settingsTab='storage';render()};$('#task-toggle').onclick=()=>modal('后台任务',S.jobs.length?S.jobs.map(j=>`<div class="setting-row"><div><h3>${esc(j.name)}</h3><p>结果保留在对应图片旁</p></div><span class="tag ${j.status==='done'?'green':''}">${{running:'进行中',done:'已完成',cancelled:'已取消'}[j.status]}</span></div>`).join(''):'<p>暂无后台任务。开始识别后可以自由切换工作空间。</p>',button('完成','close-modal','','primary'));
setInterval(()=>{if(S.record.recording){S.record.seconds++;if($('#record-time'))$('#record-time').textContent=time(S.record.seconds)}if(S.record.playing){S.record.tick=(S.record.tick+1)%13;if($('#video-time'))$('#video-time').textContent=time(S.record.tick)+' / 00:12';if($('#video-scrub'))$('#video-scrub').value=S.record.tick}},1000);window.addEventListener('resize',fitDocument);render();
